package com.student.controller;
import com.student.dao.CourseDAO; import com.student.model.Course; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class CourseServlet extends HttpServlet{private final CourseDAO dao=new CourseDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{req.setAttribute("courses",dao.findAll());req.getRequestDispatcher("/courses.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{String name=req.getParameter("courseName");if(name==null||name.isBlank())throw new IllegalArgumentException();Course c=new Course();c.setCourseName(name.trim());c.setStatus("ACTIVE");dao.save(c);resp.sendRedirect("courses?success=1");}catch(Exception e){req.setAttribute("error","Course could not be added. Make sure the name is unique.");try{req.setAttribute("courses",dao.findAll());}catch(Exception ignored){}req.getRequestDispatcher("/courses.jsp").forward(req,resp);}}}
